    await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("my-due-total")).toHaveText("");
    await expect(pg_uma.getByTestId("my-overdue-total")).toHaveText("");
    expect(await ui.bulkRetire(pg_uma, [p_fay, p_ben], "2026-03-05")).toBe(2);
    await ui.showRetired(pg_uma, true);
    expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
    expect(await ui.pasteClaims(pg_uma, "Eve,20.00,,\nZed,99.95,,\nZed,99.95,2026-03-01,")).toBeNull();
    expect(await ui.bulkGrade(pg_uma, [p_eve, p_fay], {"grade": "C", "from": "2026-03-15"})).toBe(2);
